import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";


const OrarDiscipline = () => {
  const navigate = useNavigate();
  const [activeDropdown, setActiveDropdown] = useState(null);
  const dropdownRefs = useRef([]);

  // Listă cu discipline
  const discipline = [
    "Algoritmica Grafurilor",
    "Programare Orientată pe Obiecte",
    "Sisteme de Operare",
    "Structuri de Date",
    "Teoria Limbajelor Formale",
    "Algoritmi Avansați",
    "Baze de Date",
  ];

  const toggleDropdown = (index, e) => {
    e.stopPropagation();
    setActiveDropdown((prev) => (prev === index ? null : index));
  };

  const handleDisciplinaSelect = (disciplina) => {
    navigate(`/app/orar/discipline/${disciplina}`);
  };

  return (
    <div className="orar-discipline-container">
      <div className="orar-buttons">
        {discipline.map((disciplina, index) => (
          <div className="dropdown-container" key={index} ref={(el) => (dropdownRefs.current[index] = el)}>
            <button className="orar-button" onClick={(e) => toggleDropdown(index, e)}>
              {disciplina}
            </button>
            {activeDropdown === index && (
              <div className="dropdown-menu">
                <button
                  className="dropdown-item"
                  onClick={() => handleDisciplinaSelect(disciplina)}
                >
                  {disciplina}
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default OrarDiscipline;
